import{_ as a}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as e,o as t,af as s}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const g=JSON.parse('{"title":"Claude Skills 介绍","description":"","frontmatter":{},"headers":[],"relativePath":"zh/tech/skills/claude-skills-overview.md","filePath":"zh/tech/skills/claude-skills-overview.md","lastUpdated":1787044708000}'),i={name:"zh/tech/skills/claude-skills-overview.md"};function r(o,l,d,n,h,k){return t(),e("div",null,[...l[0]||(l[0]=[s('<h1 id="claude-skills-介绍" tabindex="-1">Claude Skills 介绍 <a class="header-anchor" href="#claude-skills-介绍" aria-label="Permalink to &quot;Claude Skills 介绍&quot;">​</a></h1><blockquote><p>学习来源：<a href="https://claude.com/blog/skills" target="_blank" rel="noreferrer">https://claude.com/blog/skills</a></p></blockquote><h2 id="什么是-skills" tabindex="-1">什么是 Skills <a class="header-anchor" href="#什么是-skills" aria-label="Permalink to &quot;什么是 Skills&quot;">​</a></h2><p>Skills 是包含指令、脚本和资源的文件夹，Claude 能够<strong>动态发现并在相关任务中加载</strong>它们。可以将 Skills 理解为给 Claude 的专业化培训手册，使其在特定领域获得专业知识——从处理 Excel 电子表格到遵循组织的品牌规范。</p><h2 id="skills-的工作原理" tabindex="-1">Skills 的工作原理 <a class="header-anchor" href="#skills-的工作原理" aria-label="Permalink to &quot;Skills 的工作原理&quot;">​</a></h2><h3 id="渐进式加载-progressive-disclosure" tabindex="-1">渐进式加载（Progressive Disclosure） <a class="header-anchor" href="#渐进式加载-progressive-disclosure" aria-label="Permalink to &quot;渐进式加载（Progressive Disclosure）&quot;">​</a></h3><p>当 Claude 遇到任务时，它会扫描可用的 Skills 以找到相关匹配。Skills 使用渐进式加载：</p><ol><li><strong>元数据加载</strong>（~100 tokens）：首先加载名称和描述，提供足够信息让 Claude 知道何时激活该 Skill</li><li><strong>完整指令加载</strong>（&lt;5k tokens）：当 Skill 匹配时，加载完整指令</li><li><strong>文件/脚本按需加载</strong>：绑定的文件或脚本仅在需要时加载</li></ol><p>这种架构意味着即使有很多 Skills 可用，也不会压垮 Claude 的上下文窗口——Claude 只在需要时获取所需内容。</p><h2 id="何时使用-skills" tabindex="-1">何时使用 Skills <a class="header-anchor" href="#何时使用-skills" aria-label="Permalink to &quot;何时使用 Skills&quot;">​</a></h2><p>当需要 Claude <strong>一致且高效地执行专业化任务</strong>时，Skills 是理想选择：</p><h3 id="适用场景" tabindex="-1">适用场景 <a class="header-anchor" href="#适用场景" aria-label="Permalink to &quot;适用场景&quot;">​</a></h3><ul><li><strong>组织工作流</strong>：品牌规范、合规流程、文档模板</li><li><strong>领域专业知识</strong>：Excel 公式、PDF 操作、数据分析</li><li><strong>个人偏好</strong>：笔记系统、编码模式、研究方法</li><li><strong>标准化输出</strong>：确保每次都按相同标准执行</li></ul><h3 id="skills-vs-提示词" tabindex="-1">Skills vs 提示词 <a class="header-anchor" href="#skills-vs-提示词" aria-label="Permalink to &quot;Skills vs 提示词&quot;">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>提示词（Prompts）</th><th>Skills</th></tr></thead><tbody><tr><td>性质</td><td>临时、对话式</td><td>持久化、可复用</td></tr><tr><td>生命周期</td><td>单次对话</td><td>跨对话持久</td></tr><tr><td>加载时机</td><td>每次对话手动提供</td><td>动态自动加载</td></tr><tr><td>适用场景</td><td>一次性请求</td><td>重复性任务</td></tr></tbody></table><p><strong>经验法则</strong>：如果在多个对话中反复输入相同的提示词，那就是时候创建一个 Skill 了。</p><h2 id="skills-的核心价值" tabindex="-1">Skills 的核心价值 <a class="header-anchor" href="#skills-的核心价值" aria-label="Permalink to &quot;Skills 的核心价值&quot;">​</a></h2><h3 id="_1-编码组织知识" tabindex="-1">1. 编码组织知识 <a class="header-anchor" href="#_1-编码组织知识" aria-label="Permalink to &quot;1. 编码组织知识&quot;">​</a></h3><p>将团队的工作标准、编码规范、专业流程封装成 Skills，确保所有成员都遵循一致的标准。</p><h3 id="_2-减少重复解释" tabindex="-1">2. 减少重复解释 <a class="header-anchor" href="#_2-减少重复解释" aria-label="Permalink to &quot;2. 减少重复解释&quot;">​</a></h3><p>一次创建，长期使用。无需每次都向 Claude 解释如何执行特定任务。</p><h3 id="_3-确保执行一致性" tabindex="-1">3. 确保执行一致性 <a class="header-anchor" href="#_3-确保执行一致性" aria-label="Permalink to &quot;3. 确保执行一致性&quot;">​</a></h3><p>标准化的指令确保每次输出都符合预期质量。</p><h3 id="_4-上下文高效利用" tabindex="-1">4. 上下文高效利用 <a class="header-anchor" href="#_4-上下文高效利用" aria-label="Permalink to &quot;4. 上下文高效利用&quot;">​</a></h3><p>渐进式加载确保 Claude 的上下文窗口专注于当前任务。</p><h2 id="与其他-agent-构建块的对比" tabindex="-1">与其他 Agent 构建块的对比 <a class="header-anchor" href="#与其他-agent-构建块的对比" aria-label="Permalink to &quot;与其他 Agent 构建块的对比&quot;">​</a></h2><h3 id="skills-vs-projects" tabindex="-1">Skills vs Projects <a class="header-anchor" href="#skills-vs-projects" aria-label="Permalink to &quot;Skills vs Projects&quot;">​</a></h3><ul><li><strong>Projects</strong>：提供背景知识，Claude 在项目中工作时始终加载</li><li><strong>Skills</strong>：提供程序性知识，仅在相关时动态加载</li></ul><blockquote><p>Projects 回答&quot;我需要知道什么&quot;。Skills 回答&quot;如何做事情&quot;。</p></blockquote><h3 id="skills-vs-mcp" tabindex="-1">Skills vs MCP <a class="header-anchor" href="#skills-vs-mcp" aria-label="Permalink to &quot;Skills vs MCP&quot;">​</a></h3><ul><li><strong>MCP</strong>：连接 Claude 与数据（数据库、文件、API）</li><li><strong>Skills</strong>：教 Claude 如何处理这些数据</li></ul><p>两者配合使用：MCP 提供连接，Skills 提供流程知识。</p><h3 id="skills-vs-subagents" tabindex="-1">Skills vs Subagents <a class="header-anchor" href="#skills-vs-subagents" aria-label="Permalink to &quot;Skills vs Subagents&quot;">​</a></h3><ul><li><strong>Subagents</strong>：为特定目的构建的完整独立 agent，有自己的上下文和工具权限</li><li><strong>Skills</strong>：任何 Claude 实例都可以加载使用的可移植能力</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="品牌规范-skill" tabindex="-1">品牌规范 Skill <a class="header-anchor" href="#品牌规范-skill" aria-label="Permalink to &quot;品牌规范 Skill&quot;">​</a></h3><p>创建包含公司颜色、字体规范、布局规范的 brand-guidelines Skill。当 Claude 创建演示文稿或文档时，自动应用这些标准，无需每次解释。</p><h3 id="pdf-处理-skill" tabindex="-1">PDF 处理 Skill <a class="header-anchor" href="#pdf-处理-skill" aria-label="Permalink to &quot;PDF 处理 Skill&quot;">​</a></h3><p>包含 PDF 操作流程：文本提取、表格识别、表单填写。当需要处理 PDF 时自动激活。</p><h2 id="快速开始" tabindex="-1">快速开始 <a class="header-anchor" href="#快速开始" aria-label="Permalink to &quot;快速开始&quot;">​</a></h2><h3 id="claude-ai-用户" tabindex="-1">Claude.ai 用户 <a class="header-anchor" href="#claude-ai-用户" aria-label="Permalink to &quot;Claude.ai 用户&quot;">​</a></h3><ol><li>在 Settings → Features 中启用 Skills</li><li>在 claude.ai/projects 创建第一个项目</li><li>将项目知识与 Skills 结合使用</li></ol><h3 id="api-开发者" tabindex="-1">API 开发者 <a class="header-anchor" href="#api-开发者" aria-label="Permalink to &quot;API 开发者&quot;">​</a></h3><ul><li>在<a href="https://docs.anthropic.com" target="_blank" rel="noreferrer">官方文档</a>中探索 Skills API</li><li>参考 <a href="https://platform.claude.com/cookbook/skills-notebooks-01-skills-introduction" target="_blank" rel="noreferrer">Skills Cookbook</a></li></ul><h3 id="claude-code-用户" tabindex="-1">Claude Code 用户 <a class="header-anchor" href="#claude-code-用户" aria-label="Permalink to &quot;Claude Code 用户&quot;">​</a></h3><ul><li>通过<a href="https://code.claude.com/docs/en/plugin-marketplaces" target="_blank" rel="noreferrer">插件市场</a>安装 Skills</li><li>参考 <a href="https://platform.claude.com/cookbook/skills-notebooks-01-skills-introduction" target="_blank" rel="noreferrer">Skills Cookbook</a></li></ul><h2 id="参考资源" tabindex="-1">参考资源 <a class="header-anchor" href="#参考资源" aria-label="Permalink to &quot;参考资源&quot;">​</a></h2><ul><li><a href="https://support.claude.com/en/articles/12512176-what-are-skills" target="_blank" rel="noreferrer">Skills 官方文档</a></li><li><a href="https://github.com/anthropics/skills" target="_blank" rel="noreferrer">Anthropic Skills 库</a></li></ul>',48)])])}const S=a(i,[["render",r]]);export{g as __pageData,S as default};
